  /// đang chạy ở luồng nền
  static const TC_ANALYSIS_RUNNING = 1;

  /// xong, đọc bằng tc_analyzer_get_result
  static const TC_ANALYSIS_DONE = 2;

  /// lỗi: tc_analysis_status.result
  static const TC_ANALYSIS_FAILED = 3;

  /// bị huỷ
  static const TC_ANALYSIS_CANCELLED = 4;
}

/// Giai đoạn đang chạy, theo thứ tự (để UI hiện "Đang dò tone…").
sealed class tc_analysis_stage {
  static const TC_STAGE_NONE = 0;

  /// giải mã file
  static const TC_STAGE_DECODING = 1;

  /// đo độ to
  static const TC_STAGE_LOUDNESS = 2;

  /// chuẩn bị tín hiệu
  static const TC_STAGE_RESAMPLING = 3;

  /// tách nhạc cụ hoà âm / trống
  static const TC_STAGE_SEPARATING = 4;

  /// phổ cao độ
  static const TC_STAGE_SPECTRUM = 5;

  /// dò tone + chuyển tone
  static const TC_STAGE_KEY = 6;

  /// dò BPM
  static const TC_STAGE_TEMPO = 7;
  static const TC_STAGE_DONE = 8;
}

final class tc_analysis_status extends ffi.Struct {
  /// = sizeof(tc_analysis_status)
  @ffi.Uint32()
  external int struct_size;

  /// tc_analysis_state
  @ffi.Int32()
  external int state;

  /// tc_analysis_stage
  @ffi.Int32()
  external int stage;

  /// 0..1
  @ffi.Float()
  external double progress;

  /// tc_result của lần chạy gần nhất (TC_OK khi chưa xong)
  @ffi.Int32()
  external int result;
}

/// Một đoạn tone: [start_ms, end_ms). Kích thước cố định (dùng trong mảng) — muốn mở rộng thì
/// thêm struct mới, không sửa struct này.
final class tc_key_segment extends ffi.Struct {
  @ffi.Double()
  external double start_ms;

  @ffi.Double()
  external double end_ms;

  /// 0 = Đô (C) … 11 = Si (B)
  @ffi.Int32()
  external int root;

  /// tc_scale; phân tích chỉ trả TC_SCALE_MAJOR hoặc TC_SCALE_NATURAL_MINOR
  @ffi.Int32()
  external int scale;

  /// 0..1 (đầu vào của tc_set_key_timeline: bỏ qua)
  @ffi.Float()
  external double confidence;
}

final class tc_analysis_result extends ffi.Struct {
  /// = sizeof(tc_analysis_result)
  @ffi.Uint32()
  external int struct_size;

  @ffi.Double()
  external double duration_ms;

  /// của file gốc
  @ffi.Uint32()
  external int sample_rate;

  @ffi.Uint32()
  external int channels;

  /// 0 nếu không kết luận được (bài quá ngắn, chỉ có trống…)
  @ffi.Int32()
  external int has_key;

  @ffi.Int32()
  external int key_root;

  /// tc_scale
  @ffi.Int32()
  external int key_scale;

  @ffi.Float()
  external double key_confidence;

  @ffi.Int32()
  external int has_tuning;

  /// lệch so với La = 440 Hz, −50…+50 → đưa vào tc_set_tuning
  @ffi.Float()
  external double tuning_cents;

  @ffi.Int32()
  external int has_bpm;

  @ffi.Float()
  external double bpm;

  @ffi.Float()
  external double bpm_confidence;

  @ffi.Int32()
  external int has_loudness;

  /// ITU-R BS.1770-4
  @ffi.Float()
  external double integrated_lufs;

  @ffi.Float()
  external double sample_peak_db;

  /// số đoạn tone — đọc bằng tc_analyzer_get_key_timeline
  @ffi.Uint32()
  external int timeline_count;
}

final class tc_analyzer extends ffi.Opaque {}

/// ---- FX giọng (từ v0.6, xem docs/adr/005-fx-chain.md) ----
/// Chuỗi trên đường giọng nghe lại: micro → HPF 80 Hz → gate → chỉnh giọng → EQ → compressor →
/// de-esser → delay → reverb → trộn beat → limiter. Preset là một struct C (không JSON trong
/// engine). tc_apply_fx_preset đổi preset khi đang hát không click:
/// - khác "cấu trúc" (bật / tắt khối, loại băng EQ, thời gian delay, kiểu phòng, pre-delay) → dựng
/// chuỗi mới; phần khô crossfade 15 ms, đuôi delay / reverb của preset cũ ngân nốt (tới −80 dB,
/// tối đa 4 s);
/// - cùng cấu trúc (dB, tần số, Q, ngưỡng, tỉ lệ, độ ướt, hồi tiếp, RT60, damping…) → chuỗi đang
/// chạy trượt dần sang giá trị mới.
/// Gọi liên tiếp trước khi audio kịp nhận → chỉ lần cuối được dùng.
sealed class tc_genre {
  /// "Khô": không hiệu ứng
  static const TC_GENRE_DRY = 0;
  static const TC_GENRE_BOLERO = 1;
  static const TC_GENRE_BALLAD = 2;

  /// Nhạc trẻ
  static const TC_GENRE_POP = 3;
  static const TC_GENRE_REMIX = 4;
  static const TC_GENRE_RAP = 5;
  static const TC_GENRE_LOFI = 6;
}

sealed class tc_eq_band_type {
  static const TC_EQ_OFF = 0;
  static const TC_EQ_BELL = 3;
  static const TC_EQ_LOW_SHELF = 4;
  static const TC_EQ_HIGH_SHELF = 5;
}

sealed class tc_delay_division {
  static const TC_DELAY_OFF = 0;

  /// 1/4 nốt (theo tc_set_tempo)
  static const TC_DELAY_QUARTER = 1;

  /// 1/8
  static const TC_DELAY_EIGHTH = 2;

  /// 1/8 chấm
  static const TC_DELAY_DOTTED_EIGHTH = 3;

  /// 1/16
  static const TC_DELAY_SIXTEENTH = 4;

  /// theo delay_ms
  static const TC_DELAY_MS = 5;
}

sealed class tc_reverb_type {
  static const TC_REVERB_ROOM = 0;
  static const TC_REVERB_HALL = 1;
  static const TC_REVERB_PLATE = 2;
}

final class tc_eq_band extends ffi.Struct {
  /// tc_eq_band_type
  @ffi.Int32()
  external int type;

  @ffi.Float()
  external double freq_hz;

  /// −18..18
  @ffi.Float()
  external double gain_db;

  /// 0,1..10
  @ffi.Float()
  external double q;
}

final class tc_fx_preset extends ffi.Struct {
  /// = sizeof(tc_fx_preset); tc_fx_preset_init tự điền
  @ffi.Uint32()
  external int struct_size;

  /// EQ: thông cao / thông thấp bậc 2 (0 = tắt) + 5 băng
  @ffi.Float()
  external double eq_high_pass_hz;

  @ffi.Float()
  external double eq_low_pass_hz;

  @ffi.Array.multi([5])
  external ffi.Array<tc_eq_band> eq_bands;

  /// Compressor
  @ffi.Int32()
  external int comp_enabled;

  /// dBFS (sin toàn thang = 0)
  @ffi.Float()
  external double comp_threshold_db;

  /// ≥ 1
  @ffi.Float()
  external double comp_ratio;

  @ffi.Float()
  external double comp_knee_db;

  @ffi.Float()
  external double comp_attack_ms;

  @ffi.Float()
  external double comp_release_ms;

  @ffi.Float()
  external double comp_makeup_db;

  /// De-esser (băng 5–9 kHz, shelf 5 kHz)
  @ffi.Int32()
  external int deess_enabled;

  @ffi.Float()
  external double deess_threshold_db;

  /// 0..12
  @ffi.Float()
  external double deess_max_reduction_db;

  /// tc_delay_division
  @ffi.Int32()
  external int delay_division;

  /// khi TC_DELAY_MS: 1..2000
  @ffi.Float()
  external double delay_ms;

  /// 0..0,5
  @ffi.Float()
  external double delay_feedback;

  /// 0..1: độ lớn tiếng vọng so với tiếng khô
  @ffi.Float()
  external double delay_mix;

  @ffi.Float()
  external double delay_low_pass_hz;

  @ffi.Float()
  external double delay_high_pass_hz;

  /// Reverb (FDN 8 dòng, stereo)
  @ffi.Int32()
  external int reverb_enabled;

  /// tc_reverb_type
  @ffi.Int32()
  external int reverb_type;

  /// RT60 0,2..8
  @ffi.Float()
  external double reverb_decay_s;

  /// 0..100
  @ffi.Float()
  external double reverb_pre_delay_ms;

  /// 0..0,9: RT60 ở 4 kHz = decay · (1 − damping)
  @ffi.Float()
  external double reverb_damping;

  /// 0..1: độ lớn tiếng vang so với tiếng khô (trong băng giọng)
  @ffi.Float()
  external double reverb_mix;
}

